contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(true);
        // Acquire tokens via the airdrop entry point (blacklist starts false for this contract).
        c.getTokens();

        uint256 selfBefore = c.balanceOf(address(this));
        address recipient = address(0xA11CE);
